"use client";

import { useState } from "react";

const winningLines = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6],
];

function Mark({ value }) {
  if (value === "X") {
    return (
      <svg className="mark mark-x" viewBox="0 0 100 100" aria-hidden="true">
        <path d="M25 25 75 75M75 25 25 75" />
      </svg>
    );
  }

  if (value === "O") {
    return (
      <svg className="mark mark-o" viewBox="0 0 100 100" aria-hidden="true">
        <circle cx="50" cy="50" r="32" />
      </svg>
    );
  }

  return null;
}

export default function Home() {
  const [board, setBoard] = useState(Array(9).fill(""));
  const [currentPlayer, setCurrentPlayer] = useState("X");
  const [result, setResult] = useState(null);
  const [scores, setScores] = useState({ X: 0, O: 0, draws: 0 });
  const [round, setRound] = useState(1);

  function play(index) {
    if (result || board[index]) return;

    const nextBoard = [...board];
    nextBoard[index] = currentPlayer;
    setBoard(nextBoard);

    const winningLine = winningLines.find((line) =>
      line.every((position) => nextBoard[position] === currentPlayer),
    );

    if (winningLine) {
      setResult({ winner: currentPlayer, line: winningLine });
      setScores((previous) => ({ ...previous, [currentPlayer]: previous[currentPlayer] + 1 }));
      return;
    }

    if (nextBoard.every(Boolean)) {
      setResult({ draw: true, line: [] });
      setScores((previous) => ({ ...previous, draws: previous.draws + 1 }));
      return;
    }

    setCurrentPlayer(currentPlayer === "X" ? "O" : "X");
  }

  function startNewRound(resetMatch = false) {
    setBoard(Array(9).fill(""));
    setCurrentPlayer("X");
    setResult(null);

    if (resetMatch) {
      setScores({ X: 0, O: 0, draws: 0 });
      setRound(1);
    } else {
      setRound((previous) => previous + 1);
    }
  }

  const status = result?.winner
    ? `Player ${result.winner} wins`
    : result?.draw
      ? "It's a draw"
      : `Your move, ${currentPlayer}`;

  const message = result?.winner
    ? `${result.winner} takes the round. Nicely played.`
    : result?.draw
      ? "A draw. The rematch is already calling."
      : currentPlayer === "X" && board.every((cell) => !cell)
        ? "X goes first. Make it count."
        : `${currentPlayer}'s turn. Pick your square.`;

  return (
    <div className="page-shell" id="top">
      <header className="topbar">
        <a className="wordmark" href="#top" aria-label="Three in a Row home">
          <span className="wordmark-icon" aria-hidden="true"><i /><i /><i /></span>
          <span>THREE<br />IN A ROW</span>
        </a>
        <div className="local-label"><span className="local-dot" /> LOCAL MATCH</div>
      </header>

      <main className="game-layout">
        <section className="intro" aria-labelledby="page-title">
          <p className="eyebrow">THE CLASSIC, REMIXED <span>NO. 01</span></p>
          <h1 id="page-title">A little<br />friendly<br /><em>rivalry.</em></h1>
          <p className="intro-copy">Two players. Nine squares.<br />One very satisfying line.</p>
          <div className="how-to">
            <span className="how-to-mark" aria-hidden="true">↘</span>
            <span>Take turns. Get three<br />in a row to win.</span>
          </div>
        </section>

        <section className="play-area" aria-label="Tic tac toe game">
          <div className="game-heading">
            <div>
              <p className="eyebrow">ROUND <span>{String(round).padStart(2, "0")}</span></p>
              <h2 aria-live="polite">{status}</h2>
            </div>
            <span className={`turn-indicator ${result?.winner ? `turn-${result.winner.toLowerCase()}` : ""}`} aria-hidden="true">
              {result?.winner || (result?.draw ? "=" : currentPlayer)}
            </span>
          </div>

          <div className="board-frame">
            <div className="board" role="grid" aria-label="Tic tac toe board">
              {board.map((mark, index) => {
                const row = Math.floor(index / 3) + 1;
                const column = (index % 3) + 1;
                const winning = result?.line.includes(index);

                return (
                  <button
                    className={`cell${winning ? " winning" : ""}`}
                    type="button"
                    role="gridcell"
                    key={index}
                    aria-label={`Row ${row}, column ${column}, ${mark || "empty"}`}
                    disabled={Boolean(result) || Boolean(mark)}
                    onClick={() => play(index)}
                  >
                    <Mark value={mark} />
                  </button>
                );
              })}
            </div>
          </div>

          <div className="game-footer">
            <p className="game-message" aria-live="polite">{message}</p>
            <button className="text-button" type="button" onClick={() => startNewRound()} title="Start a new round">
              <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16.2 8A6.4 6.4 0 0 0 4.5 6.1L3 8m0 0V4.5M3 8h3.5M3.8 12a6.4 6.4 0 0 0 11.7 1.9L17 12m0 0v3.5M17 12h-3.5" /></svg>
              New round
            </button>
          </div>
        </section>

        <aside className="score-panel" aria-label="Match score">
          <div className="score-heading">
            <p className="eyebrow">THE SCORE</p>
            <span className="score-rule" aria-hidden="true" />
          </div>
          <div className="score-row score-x">
            <span className="score-symbol" aria-hidden="true">X</span>
            <div className="score-player"><span>PLAYER ONE</span><strong>{scores.X}</strong></div>
          </div>
          <div className="score-row score-o">
            <span className="score-symbol" aria-hidden="true">O</span>
            <div className="score-player"><span>PLAYER TWO</span><strong>{scores.O}</strong></div>
          </div>
          <div className="draw-row"><span>Draws</span><strong>{scores.draws}</strong></div>
          <button className="reset-button" type="button" onClick={() => startNewRound(true)}>Reset score</button>
          <p className="score-note">SAME SIDE, SAME RULES.<br />SETTLE IT ON THE BOARD.</p>
        </aside>
      </main>

      <footer className="page-footer">
        <span>THE WORLD&apos;S SMALLEST STADIUM</span>
        <span>BEST OF HOWEVER MANY</span>
      </footer>
    </div>
  );
}